function parallelStages(tasks, prerequisites) {
  const done = new Array(tasks).fill(false);
  let finished = 0;
  let stages = 0;
  while (finished < tasks) {
    const blocked = new Array(tasks).fill(false);
    for (const [before, after] of prerequisites) {
      if (!done[before]) blocked[after] = true;
    }
    const batch = [];
    for (let task = 0; task < tasks; task++) {
      if (!done[task] && !blocked[task]) batch.push(task);
    }
    if (batch.length === 0) return -1;
    for (const task of batch) done[task] = true;
    finished += batch.length;
    stages++;
  }
  return stages;
}

function parallelStages(tasks, prerequisites) {
  const unlocks = Array.from({ length: tasks }, () => []);
  const waiting = new Array(tasks).fill(0);
  for (const [before, after] of prerequisites) {
    unlocks[before].push(after);
    waiting[after]++;
  }
  let ready = [];
  for (let task = 0; task < tasks; task++) {
    if (waiting[task] === 0) ready.push(task);
  }
  let stages = 0;
  let finished = 0;
  while (ready.length > 0) {
    stages++;
    finished += ready.length;
    const nextReady = [];
    for (const task of ready) {
      for (const after of unlocks[task]) {
        waiting[after]--;
        if (waiting[after] === 0) nextReady.push(after);
      }
    }
    ready = nextReady;
  }
  return finished === tasks ? stages : -1;
}
